def transform(grid):
    out = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])
    r, c = next((i, j) for i in range(rows) for j in range(cols) if grid[i][j] == 3)
    has_obstacle = any(2 in row for row in grid)

    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    length = 2
    d = 0

    while True:
        for _ in range(2):
            dr, dc = directions[d]
            for _ in range(length):
                r += dr
                c += dc
                if not (0 <= r < rows and 0 <= c < cols):
                    if not has_obstacle:
                        out[rows - 1] = [3] * cols
                    return out
                if grid[r][c] == 2:
                    return out
                out[r][c] = 3
            d = (d + 1) % 4
        length += 2
